protected NanoHTTPD.Response serveGrid(NanoHTTPD server, Properties parms, RequestType type) {
    try {
        String query = checkArguments(parms, type);
        if (query != null) return wrap(server, query, type);
        long time = System.currentTimeMillis();
        Response response = serve();
        response.setTimeStart(time);
        if (this instanceof Request2) ((Request2) this).fillResponseInfo(response);
        if (this instanceof Parse2) ((Parse2) this).fillResponseInfo(response);
        if (type == RequestType.json)
            return response._req == null ? wrap(server, response.toJson()) : wrap(server, new String(response._req.writeJSON(new AutoBuffer()).buf()), RequestType.json);
        return wrap(server, build(response));
    } catch (RuntimeException e) {
        // Log the exception or handle it appropriately
        e.printStackTrace();
        return wrap(server, "An error occurred while processing the request.");
    }
}
